from collections import Counter

def find_blocks(grid):
    """Find all rectangular blocks of same color"""
    blocks = {}
    visited = [[False]*29 for _ in range(27)]

    for r in range(27):
        for c in range(29):
            if grid[r][c] != 1 and not visited[r][c]:
                # Expand to find rectangular block
                val = grid[r][c]
                rows = r
                cols = c
                while rows + 1 < 27 and grid[rows+1][c] == val:
                    rows += 1
                while cols + 1 < 29 and grid[r][cols+1] == val:
                    cols += 1
                # Check if consistent rectangle
                block_valid = True
                for rr in range(rows - r + 1):
                    for cc in range(cols - c + 1):
                        if grid[r + rr][c + cc] != val:
                            block_valid = False
                            break

                if block_valid and rows - r + 1 >= 2 and cols - c + 1 >= 2:
                    # Multi-cell block (min 2x2)
                    for rr in range(r, rows + 1):
                        for cc in range(c, cols + 1):
                            visited[rr][cc] = True

                # Also mark the rectangle if values are all same
                if block_valid and rows - r + 1 * (cols - c + 1) >= 1:
                    for rr in range(r, rows + 1):
                        for cc in range(c, cols + 1):
                            if grid[rr][cc] == val and (rr, cc) not in blocks:
                                blocks.setdefault(val, set()).add((rr, cc))

    return blocks

